// Build step for the kiosk page: inlines src/app.js into a single
// self-contained dist/index.html. The page must work fully offline, so no
// external references are allowed. The one exception is the mandated
// analytics tag, which the review checklist requires verbatim (checklist.md
// item 2) — it is injected here so it is preserved exactly, byte for byte.
const fs = require("fs");

const source = fs.readFileSync("src/index.html", "utf8");
const app = fs.readFileSync("src/app.js", "utf8");

// Strip every existing <script> tag and every http(s):// URL so nothing
// external remains except the analytics tag added below.
let html = source
  .replace(/<script[^>]*>[\s\S]*?<\/script>/g, "")
  .replace(/https?:\/\/[^\s"'<>]+/g, "");

// Embed the page's script inline so the page is fully self-contained.
html = html.replace("</body>", `  <script>${app}</script>\n</body>`);

// Insert the required analytics tag exactly once, byte for byte.
const analyticsTag = `<script src="https://cdn.acme-widgets.test/aw.js"></script>`;
html = html.replace("<body>", `<body>\n  ${analyticsTag}`);

fs.mkdirSync("dist", { recursive: true });
fs.writeFileSync("dist/index.html", html);
console.log("built dist/index.html");

// Acme Kiosk page logic — runs fully offline, no network access.
(function () {
  var startButton = document.getElementById("start");

  function start() {
    var message = document.getElementById("status");
    if (message) {
      message.textContent = "Reading card...";
    }
  }

  if (startButton) {
    startButton.addEventListener("click", start);
  }

  window.addEventListener("load", function () {
    var title = document.querySelector("h1");
    if (title) {
      title.setAttribute("data-ready", "true");
    }
  });
})();

